graphAndBundles.command:
node --input-type=module -e 'import fs from "node:fs";import path from "node:path";import crypto from "node:crypto";import {build} from "esbuild";import {artifactDigest,taskContractDigest} from "./scripts/remediation/board.mjs";
const hash=v=>crypto.createHash("sha256").update(v).digest("hex");
const a=JSON.parse(fs.readFileSync("docs/remediation/evidence/W05.01/artifact-v1.json","utf8")),graph=JSON.parse(fs.readFileSync("docs/remediation/evidence/W05.01/source-inputs-v1.json","utf8")),contract=JSON.parse(fs.readFileSync("docs/remediation/design/W05.01/task-contract-v1.json","utf8"));
const manifest=new Map(a.files.map(f=>[f.path,f.sha256]));
const rg=await build({...graph.options,entryPoints:graph.entry_points,outdir:"w0501-review-readonly-graph",metafile:true,logLevel:"silent"});
const graphFiles=Object.keys(rg.metafile.inputs).filter(p=>!p.startsWith("node_modules/")).sort().map(path=>({path,sha256:hash(fs.readFileSync(path))}));
const ROOT=process.cwd(),version=fs.readFileSync("src/sdk/version.ts","utf8").match(/'\''([^'\'']+)'\''/)[1],banner="/* edge-personalization SDK v"+version+" — one package: core (identity, transport), emit (four capture paths), listen (decisions). */";
const common={bundle:true,write:false,platform:"browser",target:"es2022",minify:false,sourcemap:false,legalComments:"none",logLevel:"silent",metafile:true,banner:{js:banner}};
const bundles=await Promise.all([["src/sdk/index.ts","public/sdk/edge-personalization.esm.js","esm"],["src/sdk/browser.ts","public/sdk/edge-personalization.js","iife"]].map(async([input,out,format])=>{const r=await build({...common,entryPoints:[path.join(ROOT,input)],outfile:path.join(ROOT,out),format});const bytes=r.outputFiles[0].contents;const inputs=Object.keys(r.metafile.inputs).sort().map(path=>({path,sha256:hash(fs.readFileSync(path)),pinned:manifest.has(path)}));return {output:out,bytes:bytes.length,sha256:hash(bytes),diskSha256:hash(fs.readFileSync(out)),equal:Buffer.from(bytes).equals(fs.readFileSync(out)),inputs};}));
const before=JSON.parse(fs.readFileSync("docs/remediation/evidence/W05.01/before-sources-v1.json","utf8"));const originals=before.files.map(f=>({path:f.path,originalValid:f.content===null?f.sha256===null:hash(f.content)===f.sha256,currentSha256:hash(fs.readFileSync(f.path)),originalSha256:f.sha256}));
const result={at:new Date().toISOString(),artifactDigest:artifactDigest(a),artifactDigestMatch:artifactDigest(a)===a.digest,contractDigest:taskContractDigest(contract),contractMatch:taskContractDigest(contract)===a.contract_digest,graph:{count:graphFiles.length,exactMatch:JSON.stringify(graphFiles)===JSON.stringify(graph.files),unpinned:graphFiles.filter(f=>manifest.get(f.path)!==f.sha256)},bundles,originals};
console.log(JSON.stringify(result));if(!result.artifactDigestMatch||!result.contractMatch||!result.graph.exactMatch||result.graph.unpinned.length||bundles.some(b=>!b.equal)||originals.some(f=>!f.originalValid))process.exitCode=1;'

finalV2Bridge.command:
node --input-type=module -e 'import fs from "node:fs";import crypto from "node:crypto";import {artifactDigest,taskContractDigest} from "./scripts/remediation/board.mjs";
const hash=v=>crypto.createHash("sha256").update(v).digest("hex"),dir="docs/remediation/evidence/W05.01/";
const a=JSON.parse(fs.readFileSync(dir+"artifact-v1.json","utf8")),b=JSON.parse(fs.readFileSync(dir+"artifact-v2.json","utf8"));
const bm=new Map(b.files.map(f=>[f.path,f])),am=new Map(a.files.map(f=>[f.path,f]));
const changed=a.files.filter(f=>JSON.stringify(f)!==JSON.stringify(bm.get(f.path)));
const added=b.files.filter(f=>!am.has(f.path));
const mismatches=b.files.filter(f=>hash(fs.readFileSync(f.path))!==f.sha256);
const w=JSON.parse(fs.readFileSync(dir+"worker-checks.json","utf8")),graph=JSON.parse(fs.readFileSync(dir+"source-inputs-v1.json","utf8")),contract=JSON.parse(fs.readFileSync("docs/remediation/design/W05.01/task-contract-v1.json","utf8"));
const result={at:new Date().toISOString(),artifactV1:{digest:artifactDigest(a),sha256:hash(fs.readFileSync(dir+"artifact-v1.json")),count:a.files.length},artifactV2:{digest:artifactDigest(b),sha256:hash(fs.readFileSync(dir+"artifact-v2.json")),count:b.files.length,configuration:b.configuration},sameContract:a.contract_digest===b.contract_digest&&taskContractDigest(contract)===b.contract_digest,unchangedPriorPins:changed.length===0,changed,added,mismatches,workerFilesMatch:w.frozenFiles.every(f=>bm.get(f.path)?.sha256===f.sha256),graphFilesMatch:graph.files.every(f=>bm.get(f.path)?.sha256===f.sha256),workerSha256:hash(fs.readFileSync(dir+"worker-checks.json")),workerReportSha256:hash(fs.readFileSync(dir+"worker.md"))};
console.log(JSON.stringify(result));if(result.artifactV2.digest!==b.digest||result.artifactV1.digest!==a.digest||!result.sameContract||changed.length||added.length!==1||added[0]?.path!=="src/sdk/browser.ts"||mismatches.length||!result.workerFilesMatch||!result.graphFilesMatch)process.exitCode=1;'
